import{_ as e,c as r,o as n,a2 as a}from"./chunks/framework.CIiVzG-O.js";const x=JSON.parse('{"title":"対応フォーマット","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/formats.md","filePath":"ja/guide/formats.md","lastUpdated":1793163976000}'),l={name:"ja/guide/formats.md"};function d(s,t,i,o,g,c){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="対応フォーマット" tabindex="-1">対応フォーマット <a class="header-anchor" href="#対応フォーマット" aria-label="Permalink to &quot;対応フォーマット&quot;">​</a></h1><p>NueZip は、読み取りと書き込みの両方について幅広いアーカイブフォーマットをサポートしています。以下は完全なフォーマット互換マトリックスです。</p><h2 id="フォーマットマトリックス" tabindex="-1">フォーマットマトリックス <a class="header-anchor" href="#フォーマットマトリックス" aria-label="Permalink to &quot;フォーマットマトリックス&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フォーマット</th><th style="text-align:center;">読み取り</th><th style="text-align:center;">書き込み（圧縮）</th><th style="text-align:center;">暗号化</th><th style="text-align:center;">マルチボリューム</th></tr></thead><tbody><tr><td><strong>ZIP</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256</td><td style="text-align:center;">✅</td></tr><tr><td><strong>7-Zip (.7z)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256 (LZMA2)</td><td style="text-align:center;">✅</td></tr><tr><td><strong>TAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td><strong>GZIP (.gz)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>BZIP2 (.bz2)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>XZ</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>Zstandard (.zst)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>RAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ (読み取り)</td><td style="text-align:center;">✅ (読み取り)</td></tr></tbody></table><blockquote><p><strong>注意</strong>: RAR の圧縮はライセンス制限によりサポートされていません。NueZip は、マルチボリュームや暗号化された RAR アーカイブを含め、RAR アーカイブを読み取ることができます。</p></blockquote><h2 id="フォーマットの詳細" tabindex="-1">フォーマットの詳細 <a class="header-anchor" href="#フォーマットの詳細" aria-label="Permalink to &quot;フォーマットの詳細&quot;">​</a></h2><h3 id="zip" tabindex="-1">ZIP <a class="header-anchor" href="#zip" aria-label="Permalink to &quot;ZIP&quot;">​</a></h3><ul><li><strong>圧縮</strong>: Store、Deflate、Deflate64、BZIP2、LZMA、PPMd</li><li><strong>暗号化</strong>: AES-256（推奨）、ZipCrypto（レガシー）</li><li><strong>ボリューム対応</strong>: マルチボリューム分割アーカイブ（<code>.zip.001</code>、<code>.zip.002</code>、...）</li><li><strong>最適な用途</strong>: プラットフォーム間の普遍的な互換性</li></ul><h3 id="_7-zip" tabindex="-1">7-Zip <a class="header-anchor" href="#_7-zip" aria-label="Permalink to &quot;7-Zip&quot;">​</a></h3><ul><li><strong>圧縮</strong>: LZMA2（デフォルト）、LZMA、PPMd、BZIP2、Deflate</li><li><strong>暗号化</strong>: AES-256</li><li><strong>ボリューム対応</strong>: マルチボリューム分割アーカイブ</li><li><strong>最適な用途</strong>: 最大の圧縮率</li></ul><h3 id="tar" tabindex="-1">TAR <a class="header-anchor" href="#tar" aria-label="Permalink to &quot;TAR&quot;">​</a></h3><ul><li><strong>圧縮</strong>: 非圧縮、または GZIP/BZIP2/XZ/Zstandard との組み合わせ</li><li><strong>最適な用途</strong>: Unix/Linux のアーカイブ、ファイル権限の保持</li></ul><h3 id="gzip-bzip2-xz-zstandard" tabindex="-1">GZIP / BZIP2 / XZ / Zstandard <a class="header-anchor" href="#gzip-bzip2-xz-zstandard" aria-label="Permalink to &quot;GZIP / BZIP2 / XZ / Zstandard&quot;">​</a></h3><ul><li><strong>単独の</strong> 圧縮フォーマット（単一ファイル、アーカイブのバンドルなし）</li><li>多くの場合 TAR と組み合わせて使用される（<code>.tar.gz</code>、<code>.tar.xz</code>、<code>.tar.zst</code>）</li></ul><h3 id="rar" tabindex="-1">RAR <a class="header-anchor" href="#rar" aria-label="Permalink to &quot;RAR&quot;">​</a></h3><ul><li><strong>読み取り対応</strong>: RAR4、RAR5、マルチボリューム、暗号化</li><li><strong>修復</strong>: リカバリレコードと再構築</li><li><strong>書き込み</strong>: 非対応</li></ul><h2 id="ヒント" tabindex="-1">ヒント <a class="header-anchor" href="#ヒント" aria-label="Permalink to &quot;ヒント&quot;">​</a></h2><ul><li><strong>他の人と共有する場合</strong>: <strong>ZIP</strong> を使用してください — 最も互換性の高いフォーマットです</li><li><strong>個人的なアーカイブ保存の場合</strong>: <strong>7-Zip</strong> を使用してください — 最高の圧縮率で、ディスク容量を節約できます</li><li><strong>大きなファイルの場合</strong>: <strong>分割 ZIP</strong> または <strong>分割 7-Zip</strong> を使用して、扱いやすいボリュームに分割してください</li><li><strong>機密データの場合</strong>: 常に強力なパスワードで <strong>AES-256 暗号化</strong> を有効にしてください</li></ul>',18)])])}const u=e(l,[["render",d]]);export{x as __pageData,u as default};
